independent-practice.solution:
def parse_scores(text):
    scores = {}
    number = 0
    for line in text.split("\n"):
        number += 1
        line = line.strip()
        if not line:
            continue
        parts = line.split(",")
        if len(parts) != 2:
            raise ValueError("bad line " + str(number))
        try:
            scores[parts[0]] = int(parts[1])
        except ValueError:
            raise ValueError("bad line " + str(number))
    return scores

