def apply_discount(price, code, table):
    try:
        percent = table[code]
    except KeyError:
        raise KeyError("unknown code: " + code)
    if percent < 0 or percent > 100:
        raise ValueError("percent out of range: " + str(percent))
    return round(price - price * percent / 100, 2)

